                    {
                        "use": "tagRemoveAttributeRule"
                    }
                ]
            },
            "commentRaiseEventRule": {
                "class": "HTML_Rule",
                "label": "c-r-e rule label",
                "remark": "c-r-e rule remark",
                "ruleType": "comment-raise-event"
            },
            "commentRemoveRule": {
                "class": "HTML_Rule",
                "label": "comment remove rule label",
                "remark": "comment remove rule remark",
                "ruleType": "comment-remove"
            },
            "tagAppendHtmlRule": {
                "class": "HTML_Rule",
                "label": "t-a-h rule label",
                "remark": "t-a-h rule remark",
                "ruleType": "tag-append-html",
                "content": "your code here",
                "match": {
                    "attributeName": "pie",
                    "attributeValue": "apple",
                    "tagName": "/dessert"
                }
            },
            "tagPrependHtmlRule": {
                "class": "HTML_Rule",
                "label": "t-p-h rule label",
                "remark": "t-p-h rule remark",
                "ruleType": "tag-prepend-html",
                "content": "your code here",
                "match": {
                    "attributeName": "pie",
                    "attributeValue": "cherry",
                    "tagName": "/dessert"
                }
            },
            "tagRaiseEventRule": {
                "class": "HTML_Rule",
                "label": "t-r-e rule label",
                "remark": "t-r-e rule remark",
                "ruleType": "tag-raise-event",
                "match": {
                    "attributeName": "fork",
                    "attributeValue": "missing",
                    "tagName": "utensil"
                }
            },
            "tagRemoveRule": {
                "class": "HTML_Rule",
                "label": "tag remove rule label",
                "remark": "tag remove rule remark",
                "ruleType": "tag-remove",
                "match": {
                    "attributeName": "plate",
                    "attributeValue": "dirty",
                    "tagName": "dish"
                }
            },
            "tagRemoveAttributeRule": {
                "class": "HTML_Rule",
                "label": "t-r-a rule label",
                "remark": "t-r-a remove rule remark",
                "ruleType": "tag-remove-attribute",
                "attributeName": "removeMeAttribute",
                "match": {
                    "attributeName": "attribName",
                    "attributeValue": "attribValue",
                    "tagName": "tag"
                }
            }
        }
    }
}

{
    "class": "ADC",
    "schemaVersion": "3.57.0",
    "id": "example-url-custom-accept-header",
    "label": "Custom Accept header for URL fetches",
    "remark": "Fetching certs from GitHub API with custom Accept",
    "Example_URL_Headers": {
        "class": "Tenant",
        "Example_App": {
            "class": "Application",
            "webcert": {
                "class": "Certificate",
                "remark": "Cert fetched from GitHub API with custom Accept",
                "certificate": {
                    "url": {
                        "url": "https://api.github.com/repos/myorg/myrepo/contents/certs/example.crt",
                        "headers": {
                            "Accept": "application/vnd.github.raw+json"
                        }
                    }
                },
                "privateKey": {
                    "url": {
                        "url": "https://api.github.com/repos/myorg/myrepo/contents/certs/example.key",
                        "headers": {
                            "Accept": "application/vnd.github.raw+json"
                        }
                    }
                }
            }
        }
    }
}
